/**
 * Avatars in the "Avataaars" style (getavataaars.com), version 3, drawn as inline SVG.
 *
 * The artwork is Pablo Stanley's Avataaars (MIT licence, via the avataaars library by Fang-Pen Lin),
 * converted to SVG templates; extra hair, headwear, outfits (scrubs, white coat), glasses, beards,
 * eyes, graphics and colours were drawn for this site in the same style and coordinate system
 * (264 x 280, head centre x 132). The data below is generated by tools/avatar (build.js).
 *
 * An avatar is { v: 3, t, hc, tc, a, f, fc, c, cc, g, e, b, m, s, k } (option indexes):
 *   t top (hair / headwear)  hc hair colour  tc headwear colour  a glasses / accessories
 *   f facial hair  fc its colour  c clothes  cc clothes colour  g shirt graphic
 *   e eyes  b eyebrows  m mouth  s skin  k background
 * HubAvatar.svg(config, size, sex) returns markup; HubAvatar.forAccount(acc) gives a stable default
 * figure for accounts that never designed one.
 */
(function (window) {
    'use strict';

    const D = /*__DATA__*/null;
    const VERSION = 3;
    let counter = 0;

    // ------------------------------------------------------------------
    // Template rendering: {{id:x}} unique ids, {{mask}}/{{color}}, {{slot:Name:maskVar:default}}, {{children}}
    // ------------------------------------------------------------------
    function fill(tpl, scope) {
        const p = 'av' + (++counter).toString(36) + '_';
        return tpl
            .replace(/\{\{id:(\w+)\}\}/g, (_, x) => p + x)
            .replace(/\{\{mask\}\}/g, scope.mask || '')
            .replace(/\{\{color\}\}/g, scope.color || '')
            .replace(/\{\{children\}\}/g, scope.children || '')
            .replace(/\{\{slot:(\w+):(\w*):?(\w*)\}\}/g, (_, name, v) => scope.slot(name, v ? p + v : '', scope));
    }
    const paint = (mask, color) => fill(D.colorTemplate, { mask, color, slot: () => '' });

    function render(c) {
        const slot = (name, mask) => {
            switch (name) {
                case 'HairColor': return paint(mask, D.colors.hair[c.hc]);
                case 'HatColor': return paint(mask, D.colors.hat[c.tc]);
                case 'Skin': return paint(mask, D.colors.skin[c.s]);
                case 'Colors': return paint(mask, c._facial ? D.colors.facialHair[c.fc] : D.colors.clothes[c.cc]);
                case 'Graphics': return fill(D.graphics[c.g].svg, { mask, slot });
                case 'FacialHair': return fill(D.facialHair[c.f].svg, { slot: (n, m) => n === 'Colors' ? paint(m, D.colors.facialHair[c.fc]) : '' });
                case 'Mouth': return fill(D.mouth[c.m].svg, { slot });
                case 'Nose': return fill(D.nose, { slot });
                case 'Eyes': return fill(D.eyes[c.e].svg, { slot });
                case 'Eyebrow': return fill(D.eyebrow[c.b].svg, { slot });
                default: return '';
            }
        };
        const accessories = fill(D.accessories[c.a].svg, { slot });
        const top = fill(D.top[c.t].svg, { slot, children: accessories });
        const clothes = fill(D.clothes[c.c].svg, { slot });
        const face = fill(D.face, { slot });
        const body = 'M124,144.61 L124,163 L128,163 C167.76,163 200,195.24 200,235 L200,244 L0,244 L0,235 C0,195.24 32.24,163 72,163 L76,163 L76,144.61 C58.76,136.42 46.37,119.69 44.31,99.88 C38.48,99.06 34,94.05 34,88 L34,74 C34,68.05 38.32,63.12 44,62.17 L44,56 C44,25.07 69.07,0 100,0 C130.93,0 156,25.07 156,56 L156,62.17 C161.68,63.12 166,68.05 166,74 L166,88 C166,94.05 161.52,99.06 155.69,99.88 C153.63,119.69 141.24,136.42 124,144.61 Z';
        const b = 'av' + (++counter).toString(36) + '_';
        return `<path id="${b}body" d="${body}" transform="translate(32,36)" fill="#D0C6AC"/>`
            + `<g transform="translate(32,36)"><mask id="${b}m"><path d="${body}" fill="#fff"/></mask>`
            + paint(b + 'm', D.colors.skin[c.s])
            + `<path d="M156,79 L156,102 C156,132.93 130.93,158 100,158 C69.07,158 44,132.93 44,102 L44,79 L44,94 C44,124.93 69.07,150 100,150 C130.93,150 156,124.93 156,94 L156,79 Z" fill="#000" fill-opacity=".1" mask="url(#${b}m)"/></g>`
            + clothes + face + top;
    }

    // ------------------------------------------------------------------
    // Configs
    // ------------------------------------------------------------------
    const LIMITS = {
        t: D.top.length, hc: D.colors.hair.length, tc: D.colors.hat.length, a: D.accessories.length, f: D.facialHair.length,
        fc: D.colors.facialHair.length, c: D.clothes.length, cc: D.colors.clothes.length, g: D.graphics.length,
        e: D.eyes.length, b: D.eyebrow.length, m: D.mouth.length, s: D.colors.skin.length, k: D.colors.bg.length,
    };
    const idx = (list, k) => Math.max(0, list.findIndex(x => x.k === k));
    const GRAPHIC_SHIRT = idx(D.clothes, 'GraphicShirt');

    function clean(cfg, sex) {
        const out = { v: VERSION };
        for (const [k, n] of Object.entries(LIMITS)) {
            const v = Math.floor(Number(cfg && cfg[k]));
            out[k] = Number.isFinite(v) && v >= 0 && v < n ? v : 0;
        }
        if (sex === 'f') out.f = 0;
        return out;
    }

    function svg(config, size = 40, sex) {
        const c = clean(config, sex);
        const bg = D.colors.bg[c.k];
        return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 264 264" width="${size}" height="${size}" aria-hidden="true" focusable="false" class="hav">`
            + `<rect x="0" y="0" width="264" height="264" fill="${bg}"/>`
            + `<g fill="none" fill-rule="evenodd">${render(c)}</g></svg>`;
    }

    function hashCode(str) {
        let h = 2166136261;
        for (let i = 0; i < str.length; i++) { h ^= str.charCodeAt(i); h = Math.imul(h, 16777619); }
        return h >>> 0;
    }
    const pick = (list, keys) => keys.map(k => list.findIndex(x => x.k === k)).filter(i => i >= 0);

    /** A stable, professional default figure for an account that never designed one. */
    function defaultFor(seed, sex) {
        let h = hashCode(String(seed || 'x'));
        const next = n => { const v = h % n; h = (Math.imul(h ^ (h >>> 15), 2246822507) >>> 0) || 1; return v; };
        const one = arr => arr[next(arr.length)];
        const female = sex === 'f';
        const tops = female
            ? pick(D.top, ['Hijab', 'Hijab', 'Hijab', 'LongHairStraight', 'LongHairBun', 'LongHairBob', 'LongHairNotTooLong', 'LongHairCurvy'])
            : pick(D.top, ['ShortHairShortFlat', 'ShortHairShortRound', 'ShortHairTheCaesar', 'ShortHairTheCaesarSidePart', 'ShortHairShortWaved', 'ShortHairBuzz', 'ShortHairSlick']);
        return clean({
            t: one(tops), hc: one([1, 1, 5, 5, 4, 0]), tc: next(LIMITS.tc), a: next(4) === 0 ? one(pick(D.accessories, ['Prescription01', 'Prescription02', 'Round'])) : 0,
            f: female ? 0 : one(pick(D.facialHair, ['Blank', 'BeardLight', 'BeardMedium', 'Stubble', 'Goatee', 'BeardLight'])), fc: one([1, 5, 4]),
            c: one(pick(D.clothes, ['Scrubs', 'ScrubsStethoscope', 'WhiteCoat', 'WhiteCoatStethoscope', 'BlazerShirt', 'CollarSweater'])),
            cc: next(LIMITS.cc), g: 0, e: one(pick(D.eyes, ['Default', 'Happy', 'Default'])), b: one(pick(D.eyebrow, ['Default', 'DefaultNatural', 'FlatNatural'])),
            m: one(pick(D.mouth, ['Smile', 'Default', 'Twinkle'])), s: next(LIMITS.s), k: next(LIMITS.k),
        }, sex);
    }

    /** Parsed avatar of an account (or its default figure). Older designs are replaced by the default. */
    function forAccount(acc) {
        if (!acc) return null;
        let cfg = acc.avatar;
        if (typeof cfg === 'string') { try { cfg = JSON.parse(cfg); } catch (e) { cfg = null; } }
        return cfg && typeof cfg === 'object' && cfg.v === VERSION ? clean(cfg, acc.sex) : defaultFor(acc.name || acc.username || acc.id, acc.sex);
    }

    const NOT_EVERYDAY = new Set(['Cry', 'Dizzy', 'Vomit', 'ScreamOpen', 'Hearts', 'Eyepatch', 'Angry', 'AngryNatural', 'Grimace']);
    function random(sex) {
        const r = n => Math.floor(Math.random() * n);
        const ok = (list, i) => !NOT_EVERYDAY.has(list[i].k);
        const any = list => { let i; do { i = r(list.length); } while (!ok(list, i)); return i; };
        const female = sex === 'f';
        const femaleTops = D.top.map((t, i) => i).filter(i => /^(Long|Hijab)/.test(D.top[i].k) || D.top[i].both);
        const maleTops = D.top.map((t, i) => i).filter(i => /^(Short|NoHair|Turban|Hat|Winter|Kufi)/.test(D.top[i].k) || D.top[i].both);
        return clean({
            t: female ? femaleTops[r(femaleTops.length)] : maleTops[r(maleTops.length)], hc: r(LIMITS.hc), tc: r(LIMITS.tc),
            a: r(3) ? 0 : any(D.accessories), f: female || r(2) ? 0 : any(D.facialHair), fc: r(LIMITS.fc), c: any(D.clothes), cc: r(LIMITS.cc),
            g: r(LIMITS.g), e: any(D.eyes), b: any(D.eyebrow), m: any(D.mouth), s: r(LIMITS.s), k: r(LIMITS.k),
        }, sex);
    }

    // Parts of the editor (account panel): options drawn on the current figure, colour rows per part.
    const PARTS = [
        { key: 's', label: 'البشرة', colors: D.colors.skin },
        { key: 't', label: 'الشعر وغطاء الرأس', options: D.top.map(x => x.label), color: 'hc', palette: D.colors.hair },
        { key: 'tc', label: 'لون غطاء الرأس', colors: D.colors.hat },
        { key: 'e', label: 'العيون', options: D.eyes.map(x => x.label) },
        { key: 'b', label: 'الحواجب', options: D.eyebrow.map(x => x.label) },
        { key: 'm', label: 'الفم', options: D.mouth.map(x => x.label) },
        { key: 'f', label: 'اللحية والشارب', options: D.facialHair.map(x => x.label), color: 'fc', palette: D.colors.facialHair, male: true },
        { key: 'a', label: 'النظارات والإكسسوارات', options: D.accessories.map(x => x.label) },
        { key: 'c', label: 'الملابس', options: D.clothes.map(x => x.label), color: 'cc', palette: D.colors.clothes },
        { key: 'g', label: 'رسمة التيشيرت', options: D.graphics.map(x => x.label), requires: { c: GRAPHIC_SHIRT } },
        { key: 'k', label: 'الخلفية', colors: D.colors.bg },
    ];

    window.HubAvatar = {
        svg, forAccount, defaultFor, clean, random, PARTS, LIMITS, VERSION, _data: D,
        palettes: { SKIN: D.colors.skin, HAIR_COLOR: D.colors.hair, HAT_COLOR: D.colors.hat, CLOTH_COLOR: D.colors.clothes, BG: D.colors.bg },
    };
})(window);
